SELECT resource_ref FROM audit_event a WHERE audit_id=#{auditId} AND subject_id=#{userId}
  AND project_id <=> #{projectId} AND action='model.configuration_saved' AND result='SUCCESS' AND reason_code IS NULL
  AND request_id=#{requestId} AND trace_id=#{requestId} AND schema_version='1.0.0'
  AND schema_manifest_sha256=#{manifest} AND created_by=#{userId} AND classification=#{classification}
